lessons.starter:
CREATE VIEW labels AS
SELECT id,owner AS label
FROM parcels;

lessons.solution:
CREATE VIEW labels AS
SELECT id,owner || ': ' || (quantity + 1) AS label
FROM parcels;
SELECT *
FROM labels
ORDER BY id;

