lessons.starter:
CREATE VIEW prefixes AS
SELECT id,name AS prefix,0 AS size
FROM names;

lessons.solution:
CREATE VIEW prefixes AS
SELECT id,substr(name,1,3) AS prefix,length(name) AS size
FROM names;
SELECT *
FROM prefixes
ORDER BY id;

lessons.starter:
CREATE VIEW shares AS
SELECT id,total/people AS average
FROM supplies;

lessons.solution:
CREATE VIEW shares AS
SELECT id,CAST(total AS REAL)/people AS average
FROM supplies;
SELECT *
FROM shares
ORDER BY id;

